(* Point on the radius-150 circle centered at (200, 200) for an hour 0..12. *)
let find_endpoint (time : int) : Gctx.position =
  let angle = float_of_int (time mod 12) *. Float.pi /. 6. in
  (200 + int_of_float (Float.round (150. *. sin angle)),
   200 - int_of_float (Float.round (150. *. cos angle)))

let clock (init : int) : widget * notifier_controller * int value_controller =
  let time = make_controller (init mod 12) in
  let repaint (g : Gctx.gctx) : unit =
    let c : Gctx.position = (200, 200) in (* center *)
    let r : int = 150 in (* radius *)
    Gctx.draw_ellipse g c r r;
    Gctx.draw_line g c (find_endpoint (time.get_value ()))
  in
  let clock_w, nc = canvas (400, 400) repaint in
  (clock_w, nc, time)

